import{_ as e,o as t,c as r,aU as o}from"./chunks/framework.BWaOKJaB.js";const _=JSON.parse('{"title":"周玉的个人博客","description":"记录个人思考和成长，分享个人经验和见解。","frontmatter":{"title":"周玉的个人博客","description":"记录个人思考和成长，分享个人经验和见解。"},"headers":[],"relativePath":"博客/index.md","filePath":"02.博客/index.md","lastUpdated":0}'),l={name:"博客/index.md"};function i(n,a,d,c,h,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="宠辱不惊-看庭前花开花落" tabindex="-1">宠辱不惊，看庭前花开花落 <a class="header-anchor" href="#宠辱不惊-看庭前花开花落" aria-label="Permalink to “宠辱不惊，看庭前花开花落”">​</a></h1><h1 id="去留无意-望天上云卷云舒" tabindex="-1">去留无意，望天上云卷云舒 <a class="header-anchor" href="#去留无意-望天上云卷云舒" aria-label="Permalink to “去留无意，望天上云卷云舒”">​</a></h1><h2 id="时间比钱重要" tabindex="-1">时间比钱重要 <a class="header-anchor" href="#时间比钱重要" aria-label="Permalink to “时间比钱重要”">​</a></h2><blockquote><p>这世界对于每个人而言，唯一不可再生的就是时间，能够充分利用时间创造价值的人，时间会给予他最大的回报。</p></blockquote><h2 id="允许一切发生" tabindex="-1">允许一切发生 <a class="header-anchor" href="#允许一切发生" aria-label="Permalink to “允许一切发生”">​</a></h2><blockquote><p>当有一天，不如愿的事情发生，你心里再多难过，也心如止水地坦然接受，这就是成熟。</p></blockquote><h2 id="低调是智慧" tabindex="-1">低调是智慧 <a class="header-anchor" href="#低调是智慧" aria-label="Permalink to “低调是智慧”">​</a></h2><blockquote><p>有能力的人从不会期待得到外界的认可，他们只管做好自己的事情。反观越是争强好胜的人，其实内心是虚慌的，自己都不能接受自己的，所以他们只能四处摆弄，通过外界的反馈给自己带来感觉良好的错觉。</p><p>低调聪明的人，其实都懂得说话留一线，避免夸大自己，日后被人要求做能力不够的事情犯尴尬。与其违心说高大空的假话让别人听着舒服，不如给自己留个面子和退路。</p><p>你以为你吹出来的牛逼，在别人眼里会高看你一眼吗？错！其实他们也不过会觉得这是你能力范围内本就应该的而已。相反，你若低调一点，别人还能够慧眼识珠收入麾下，那日后你的聪明才能更加让你平步青云，一路顺遂。</p></blockquote><h2 id="时势与胆识" tabindex="-1">时势与胆识 <a class="header-anchor" href="#时势与胆识" aria-label="Permalink to “时势与胆识”">​</a></h2><blockquote><p>当某天你回首来时路，才发现，原来一切都是时势造英雄，并没有什么经验可以总结给别人。</p><p>一切的成就，既不是自己多努力，也不是自己多聪明，而是看准和敢把握每一个可能的机遇的慧眼和胆量，并为之付出一切去实现。</p><p>聪明的人大有人在，但是迈向未知的勇气和顽强克服一切的心力这又是另一种关于成功难能可贵的品质！</p></blockquote>',10)])])}const b=e(l,[["render",i]]);export{_ as __pageData,b as default};
